                        var prTitle = pr.title || '';
                        var prBranch = (pr.head && pr.head.ref) || '';
                        if (prTitle.indexOf(ticketKey) !== -1 || prBranch.indexOf(ticketKey) !== -1) {
                            featurePrUrl = pr.html_url || pr.url || '';
                            featurePrNumber = String(pr.number || '');
