        console.log('🚀 Bitrise Test Automation Proxy');
        console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
        console.log('Ticket:', ticketKey, '—', ticketSummary);

