        var workflowId = bb.workflowId || 'ai_teammate_test_automation';
        var branch = bb.branch || 'main';

        if (!appSlug) {
            console.error('❌ customParams.bitriseBuild.appSlug is required');
            return { success: false, error: 'Missing bitriseBuild.appSlug' };
        }

