            '| Field | Value |\n|-------|-------|\n' +
            '| Workflow | ' + workflowId + ' |\n' +
            '| Branch | ' + branch + ' |';
        if (buildUrl) comment += '\n| Build | [View on Bitrise|' + buildUrl + '] |';
        if (featurePrUrl) comment += '\n| Feature PR | ' + featurePrUrl + ' |';

