                    var results = tracker.searchIssues(jql, { maxResults: 1 });
                    var parsed = (typeof results === 'string') ? JSON.parse(results) : results;
                    var issues = (parsed && parsed.issues) ? parsed.issues : (Array.isArray(parsed) ? parsed : []);
