/**
 * Unit tests for js/triggerStoryTestAutomation.js
 */

function loadTriggerStoryTestAutomation(mocks) {
    var defaults = {
        jira_remove_label: function() {},
        jira_post_comment: function() {}
    };

    var allMocks = Object.assign({}, defaults, mocks);
    var trackersMod = loadModule('js/common/trackers.js', makeRequire({
        '../config.js': configModule,
        './ticketKeyShapes.js': loadModule('js/common/ticketKeyShapes.js')
    }), allMocks);
    return loadModule(
        'js/triggerStoryTestAutomation.js',
        makeRequire({
            './common/trackers.js': trackersMod,
            './common/autoStart.js': {
                triggerConfiguredWorkflowForTicket: function(opts) {
                    return (mocks && mocks.triggerConfiguredWorkflowForTicket)
                        ? mocks.triggerConfiguredWorkflowForTicket(opts)
                        : false;
                },
                triggerSmIfIdle: function(opts) {
                    return (mocks && mocks.triggerSmIfIdle)
                        ? mocks.triggerSmIfIdle(opts)
                        : { success: true };
                }
            },
            './common/tokenUsageComment.js': {
                postTokenUsageComments: function(key, opts) {
                    if (mocks && mocks.postTokenUsageComments) mocks.postTokenUsageComments(key, opts);
                }
            }
        }),
        allMocks
    );
}

suite('triggerStoryTestAutomation', function() {

    test('triggers story_test_automation and removes SM label', function() {
        var triggered = false;
        var removedLabels = [];
        var tokenKeys = [];

        var module = loadTriggerStoryTestAutomation({
            triggerConfiguredWorkflowForTicket: function(opts) {
                triggered = true;
                assert.equal(opts.ticketKey, 'TS-100');
                assert.equal(opts.configFile, 'agents/story_test_automation.json');
                assert.equal(opts.label, 'story_test_automation');
                return true;
            },
            jira_remove_label: function(args) { removedLabels.push(args); },
            postTokenUsageComments: function(key) { tokenKeys.push(key); }
        });

        var result = module.action({
            ticket: { key: 'TS-100' },
            jobParams: {
                customParams: {
                    removeLabel: 'sm_test_cases_triggered',
                    autoStartStoryTestAutomation: true,
                    autoStartStoryTestAutomationConfigFile: 'agents/story_test_automation.json'
                }
            }
        });

        assert.equal(result.success, true);
        assert.equal(result.triggered, true);
        assert.equal(triggered, true);
        assert.deepEqual(removedLabels, [{ key: 'TS-100', label: 'sm_test_cases_triggered' }]);
        assert.deepEqual(tokenKeys, ['TS-100']);
    });

    test('falls back to SM trigger when autoStart is disabled', function() {
        var smTriggered = false;
        var removedLabels = [];

        var module = loadTriggerStoryTestAutomation({
            triggerSmIfIdle: function() { smTriggered = true; return { success: true }; },
            jira_remove_label: function(args) { removedLabels.push(args); }
        });

        var result = module.action({
            ticket: { key: 'TS-101' },
            jobParams: {
                customParams: { removeLabel: 'sm_test_cases_triggered' }
            }
        });

        assert.equal(result.success, true);
        assert.equal(result.triggered, false);
        assert.equal(smTriggered, true);
        assert.deepEqual(removedLabels, [{ key: 'TS-101', label: 'sm_test_cases_triggered' }]);
    });

});

/**
 * DMTools Agent Unit Test Runner
 *
 * Runs unit tests for agent JS scripts in GraalJS environment.
 * Provides: test(), suite(), assert, loadModule(), makeRequire(), trackersMock()
 *
 * Usage:
 *   dmtools run js/unit-tests/run_all.json
 *   dmtools run js/unit-tests/run_configLoader.json
 *   dmtools run js/unit-tests/run_smAgent.json
 */

// ── Global state ─────────────────────────────────────────────────────────────

var _results_ = { passed: 0, failed: 0, errors: [] };
var _currentSuite_ = 'default';

// Provide a stub java global for tests that mock java.lang.System.getenv.
// In a real GraalJS environment java is already present; we never overwrite it.
if (typeof java === 'undefined') {
    var _javaStub_ = { lang: { System: { getenv: function() { return null; } } } };
    if (typeof globalThis !== 'undefined') {
        globalThis.java = _javaStub_;
    } else if (typeof this !== 'undefined') {
        this.java = _javaStub_;
    }
}

// ── Network guard ────────────────────────────────────────────────────────────
// Unit tests must never reach a real service. Several tests fall through to the
// REAL host tool (github_*, confluence_* ...) when they do not mock it, which issued
// ~100 real api.github.com / atlassian.net requests per run (each a 401 after a
// round-trip, ~40 s locally, flaky offline, and a rate-limit risk with a real token).
// Replace every network-backed integration tool with one that throws — the same
// failure mode the tests already tolerate from a 401 — while file_*, cli_*, kb_* and
// mermaid_* stay real. Tests that mock a tool through loadModule() shadow it locally
// and are unaffected.
var NETWORK_TOOL_PREFIXES_ = [
    'github', 'gitlab', 'bitbucket', 'jira', 'xray', 'confluence', 'ado', 'rally',
    'figma', 'teams', 'sharepoint', 'bitrise', 'jenkins', 'testrail', 'tracker',
    'source', 'gemini', 'openai', 'anthropic', 'bedrock', 'dial', 'ollama', 'vertex'
];

function installNetworkGuard_() {
    var g = (typeof globalThis !== 'undefined') ? globalThis : this;
    var guarded = 0;
    Object.getOwnPropertyNames(g).forEach(function(name) {
        var m = /^([a-z0-9]+)_/.exec(name);
        if (!m || NETWORK_TOOL_PREFIXES_.indexOf(m[1]) === -1) return;
        if (typeof g[name] !== 'function') return;
        try {
            g[name] = function() {
                throw new Error('unit-test network guard: ' + name + '() is not mocked — ' +
                    'unit tests must not call real services');
            };
            guarded++;
        } catch (e) { /* non-writable binding — leave as is */ }
    });
    return guarded;
}

// Pre-loaded base modules available to all test files as globals
var configModule = null;
var configLoaderModule = null;

// ── Test API (globals usable in test files) ──────────────────────────────────

function test(name, fn) {
    var fullName = _currentSuite_ + ' > ' + name;
    try {
        fn();
        _results_.passed++;
        console.log('  ✅ ' + fullName);
    } catch (e) {
        _results_.failed++;
        var msg = e.message || String(e);
        _results_.errors.push({ name: fullName, error: msg });
        console.log('  ❌ ' + fullName);
        console.log('     ' + msg);
    }
}

function suite(name, fn) {
    var prev = _currentSuite_;
    _currentSuite_ = name;
    console.log('\n── ' + name + ' ──');
    fn();
    _currentSuite_ = prev;
}

// ── Assert library ────────────────────────────────────────────────────────────

var assert = {
    equal: function(actual, expected, msg) {
        if (actual !== expected) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                'expected ' + JSON.stringify(expected) + ' but got ' + JSON.stringify(actual)
            );
        }
    },

    notEqual: function(actual, unexpected, msg) {
        if (actual === unexpected) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                'expected value to not equal ' + JSON.stringify(unexpected)
            );
        }
    },

    deepEqual: function(actual, expected, msg) {
        var a = JSON.stringify(actual);
        var b = JSON.stringify(expected);
        if (a !== b) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                '\n  expected: ' + b +
                '\n  actual:   ' + a
            );
        }
    },

    ok: function(val, msg) {
        if (!val) {
            throw new Error(msg || ('expected truthy, got: ' + JSON.stringify(val)));
        }
    },

    notOk: function(val, msg) {
        if (val) {
            throw new Error(msg || ('expected falsy, got: ' + JSON.stringify(val)));
