                try {
                    var t = tracker.getIssue(ticketKeyFromJql);
                    if (t && t.key) {
                        params = { ticket: t, jobParams: params.jobParams };
                    } else {
                        return { success: false, error: 'Could not fetch ticket: ' + ticketKeyFromJql };
