        var workflowId = bb.workflowId || 'build_ios_simulator';
        var triggerBranch = bb.triggerBranch || '';
        var featurePRConfig = jobParams.featurePR || {};
        var featureOwner = featurePRConfig.owner || '';
        var featureRepo = featurePRConfig.repo || '';

