                    var issues = (parsed && parsed.issues) ? parsed.issues : (Array.isArray(parsed) ? parsed : []);
                    if (issues.length > 0) {
                        ticketKey = issues[0].key;
                        ticketSummary = (issues[0].fields && issues[0].fields.summary) || ticketKey;
