// Coverage runner for the crap4js quality gate (dmtools-agents).
//
// Executes the node test harness (js/unit-tests/node_testRunner.js) against
// the nyc-INSTRUMENTED copy of the repo and dumps global.__coverage__ in
// Istanbul coverage-final.json format for crap4js.
//
// Why the dance: the harness loads every module through its own
// loadModule()/eval() (mock injection), which bypasses nyc's require hook —
// a plain `nyc node node_testRunner.js` instruments nothing. Pre-instrumenting
// the tree with `nyc instrument` bakes the Istanbul counters into the sources
// themselves, so eval'd code reports coverage through the global.
//
// Usage:
//   node ci/run_with_coverage.js <runner.js> <coverage-out.json> [testFiles...]
//
// Exit code = the harness's exit code (0 = all tests passed). Coverage is
// written regardless of test failures — the canonical suite green-gate is
// the pack-release test job (`dmtools run js/unit-tests/run_all.json`);
// this node harness is a coverage vehicle, and its known mock gaps
// (see the quality workflow) must not block coverage collection.

const fs = require('fs');
const path = require('path');

const runner = process.argv[2];
const outFile = process.argv[3];
const testFiles = process.argv.slice(4);

const origExit = process.exit;
let exitCode = 0;
process.exit = (c) => { exitCode = c || 0; throw { __coverage_exit__: true }; };
process.argv = [process.argv[0], runner].concat(testFiles);

try {
  require(runner);
} catch (e) {
  if (!e || !e.__coverage_exit__) {
    console.error(e);
    origExit(2);
  }
}
fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, JSON.stringify(global.__coverage__ || {}));
console.log('coverage written: ' + outFile + ' (' +
  Object.keys(global.__coverage__ || {}).length + ' files)');
origExit(exitCode);

/**
 * Node-based test harness for agent unit tests.
 *
 * Mirrors the GraalJS testRunner API so the same test files can be executed
 * in environments where the dmtools JSRunner is not available.
 * Provides: test(), suite(), assert, loadModule(), makeRequire(), trackersMock()
 */

const fs = require('fs');
const path = require('path');

var _results_ = { passed: 0, failed: 0, errors: [] };
var _currentSuite_ = 'default';

function test(name, fn) {
    var fullName = _currentSuite_ + ' > ' + name;
    try {
        fn();
        _results_.passed++;
        console.log('  ✅ ' + fullName);
    } catch (e) {
        _results_.failed++;
        var msg = e.message || String(e);
        _results_.errors.push({ name: fullName, error: msg });
        console.log('  ❌ ' + fullName);
        console.log('     ' + msg);
    }
}

function suite(name, fn) {
    var prev = _currentSuite_;
    _currentSuite_ = name;
    console.log('\n── ' + name + ' ──');
    fn();
    _currentSuite_ = prev;
}

var assert = {
    equal: function(actual, expected, msg) {
        if (actual !== expected) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                'expected ' + JSON.stringify(expected) + ' but got ' + JSON.stringify(actual)
            );
        }
    },
    notEqual: function(actual, unexpected, msg) {
        if (actual === unexpected) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                'expected value to not equal ' + JSON.stringify(unexpected)
            );
        }
    },
    deepEqual: function(actual, expected, msg) {
        var a = JSON.stringify(actual);
        var b = JSON.stringify(expected);
        if (a !== b) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                '\n  expected: ' + b +
                '\n  actual:   ' + a
            );
        }
    },
    ok: function(val, msg) {
        if (!val) {
            throw new Error(msg || ('expected truthy, got: ' + JSON.stringify(val)));
        }
    },
    notOk: function(val, msg) {
        if (val) {
            throw new Error(msg || ('expected falsy, got: ' + JSON.stringify(val)));
        }
    },
    contains: function(str, substr, msg) {
        if (typeof str !== 'string' || str.indexOf(substr) === -1) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                JSON.stringify(str) + ' does not contain ' + JSON.stringify(substr)
            );
        }
    },
    notContains: function(str, substr, msg) {
        if (typeof str === 'string' && str.indexOf(substr) !== -1) {
            throw new Error(
                (msg ? msg + ': ' : '') +
                JSON.stringify(str) + ' should not contain ' + JSON.stringify(substr)
            );
        }
    },
    throws: function(fn, msg) {
        var threw = false;
        try { fn(); } catch (e) { threw = true; }
        if (!threw) {
            throw new Error(msg || 'expected function to throw but it did not');
        }
    }
};

function file_read(args) {
