        assert.equal(r.success, true);
        assert.equal(iosCalls(rec, 'bitrise_trigger_build')[0].args.commitMessage, 'IOS-4 — iOS build for develop');
        assert.equal(iosCalls(rec, 'postComment')[0].key, 'IOS-4');
    });

