        return true;
    } catch (abortErr) {
        console.warn('⚠️ Could not abort build ' + b.slug + ':', abortErr.message || abortErr);
        return false;
    }
}

function abortBuildsForTicket(appSlug, builds, ticketKey) {
    var abortedCount = 0;
    for (var bi = 0; bi < builds.length; bi++) {
