        if (prMatchesTicket(pr, ticketKey)) {
            var branch = prHeadRef(pr) || defaultBranch;
            console.log('✅ Found feature PR #' + pr.number + ' → branch: ' + branch);
            return { branch: branch, url: prViewUrl(pr) };
        }
