        if (pr) {
            result.branch = pr.branch || result.branch;
            result.url = pr.url;
        } else {
            console.log('ℹ️ No open feature PR found — triggering on develop');
        }
    } catch (e) {
        console.warn('⚠️ Could not search PRs:', e.message || e);
    }
    return result;
}

