    return (b.commit_message || '').indexOf(ticketKey) !== -1 && !!b.slug;
}

function abortOneBuild(appSlug, b, ticketKey) {
    try {
        bitrise_abort_build({
            appSlug: appSlug,
            buildSlug: b.slug,
