     function fetchTicketByKey(tracker, key) {
         console.log('JSRunner mode — fetching ticket by key:', key);
         try {
             var t = tracker.getIssue(key);
             return (t && t.key) ? { ticket: t } : { error: 'Could not fetch ticket: ' + key };  // +1 &&, +1 ternary
