        assert.deepEqual(
            mod.resolveTicketParams({ inputJql: 'label = z' }, { searchIssues: function() { return []; } }),
            { error: 'No tickets found for JQL: label = z' });
    });

    test('pickActualParams and resolveCustomParams tier order', function() {
